import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Session validation middleware
async function validateSession(req, res, next) {
  const sessionToken = req.headers['x-session-token'];
  if (!sessionToken) return res.status(401).json({ error: 'No session' });

  const result = await pool.query(
    'SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()',
    [sessionToken]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid session' });
  req.user = result.rows[0];
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', validateSession, async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;

    // Base query with parameterized search term
    let queryText = `SELECT d.id, d.title, d.category, d.created_at, d.owner_id
      FROM documents d
      WHERE d.org_id = $1`;
    let params = [req.user.org_id || 1];
    let paramIdx = 2;

    if (q) {
      queryText += ` AND d.search_vector @@ plainto_tsquery('english', $${paramIdx})`;
      params.push(q);
      paramIdx++;
    }

    if (category) {
      queryText += ` AND d.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Sort handling - validated against allowlist... partially
    const allowedSortColumns = ['created_at', 'title', 'category', 'updated_at'];
    const sortColumn = sort_by && allowedSortColumns.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

    queryText += ` ORDER BY d.${sortColumn} ${sortOrder}`;

    // Limit handling - this is where the injection lives
    const parsedLimit = limit ? limit : '50';
    queryText += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(queryText, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document detail with IDOR potential
app.get('/api/v2/documents/:id', validateSession, async (req, res) => {
  try {
    const docId = req.params.id;
    // Note: no org_id check here - relies on network-level isolation
    const result = await pool.query(
      'SELECT * FROM documents WHERE id = $1',
      [docId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Admin export - intentionally looks dangerous but is session-gated
app.post('/api/v2/admin/export', validateSession, async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  const { query_override } = req.body;
  // Looks scary but admin-only
  const result = await pool.query(query_override);
  res.json({ data: result.rows });
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Document service running on port ${process.env.PORT || 3000}`);
});

export default app;
